let toastTimer,fetchSequence=0;
function node(tag,attrs={},...children){const n=document.createElement(tag);for(const[k,v]of Object.entries(attrs)){if(v===undefined||v===null)continue;if(k==='class')n.className=v;else if(k==='text')n.textContent=v;else if(k==='onClick')n.onclick=v;else if(k==='style')n.setAttribute(k,v);else n.setAttribute(k,v);}for(const child of children.flat())if(child!=null)n.append(typeof child==='string'?document.createTextNode(child):child);return n;}
function say(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,6500);}
