function saveDrafts(events){const combinedIds=new Set([...state.publicDoc.events,...events].map(e=>e.id));if(events.length>1500||combinedIds.size>1500){say('공용 일정과 초안을 합쳐 최대 1,500개까지 저장할 수 있어요. 기존 초안은 유지했어요.');return false;}if(state.draftReadOnly){say('기존 초안을 읽을 수 없어 덮어쓰지 않았어요. 브라우저 저장 설정을 확인해 주세요.');return false;}try{localStorage.setItem(STORE,JSON.stringify({version:1,timezone:C.ZONE,publishedAt:null,events}));state.drafts=events;return true;}catch{say('브라우저에 저장하지 못했어요. 저장 공간·브라우저 설정을 확인해 주세요.');return false;}}
