function periodLabel(){const list=days(),f=d=>`${Number(d.slice(5,7))}.${Number(d.slice(8))}`;if(list.length===7)return list[0].slice(0,4)===list[6].slice(0,4)?`${list[0].slice(0,4)}. ${f(list[0])} – ${f(list[6])}`:`${list[0].slice(0,4)}.${f(list[0])} – ${list[6].slice(0,4)}.${f(list[6])}`;return `${state.date.slice(0,4)}. ${f(state.date)} (${['일','월','화','수','목','금','토'][new Date(state.date+'T12:00:00Z').getUTCDay()]})`;}

